/* pricing */
.pr{width:100%;max-width:900px}
.pr-top{display:flex;align-items:center;justify-content:center;gap:10px;margin-bottom:16px}
.pr-save{font-size:12.5px;font-weight:600;color:var(--success)}
.pr-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.pr-c{display:flex;flex-direction:column;padding:20px;background:var(--panel);border:1px solid var(--line)}
.pr-c.pop{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg)}
.pr-n{display:flex;align-items:center;justify-content:space-between;font-size:14px;font-weight:600}
.pr-n .tag{font-size:11px}
.pr-p{display:flex;align-items:baseline;gap:4px;margin:14px 0 4px}
.pr-p b{font-family:var(--mono);font-size:32px;font-weight:700;letter-spacing:-1px}
.pr-p span{font-size:13px;color:var(--muted)}
.pr-d{min-height:40px;font-size:13px;line-height:1.5;color:var(--text-dim)}
.pr-c .btn{justify-content:center;margin:14px 0 16px}
.pr-f{display:flex;flex-direction:column;gap:8px;padding-top:14px;border-top:1px solid var(--line)}
.pr-f span{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--text-dim)}
.pr-f .ms{color:var(--success);font-size:14px}

/* pricing: the yearly saving sits inside its chip */
.pr-badge{display:inline-flex;align-items:center;margin-left:6px;padding:1px 6px;font-size:10.5px;font-weight:700;color:#159a63;background:rgba(21,154,99,.12);border:1px solid rgba(21,154,99,.25);vertical-align:1px}
[data-style="soft"] .pr-badge{border-radius:999px}

/* pricing: even space above and below, softer highlight */
#c70 .stage-inner{padding-bottom:62px}
[data-style="soft"] .pr-c.pop{box-shadow:0 0 0 3px rgba(17,111,248,.08),0 12px 28px -22px rgba(17,111,248,.32)}
.pr-c.pop{box-shadow:0 0 0 2px var(--accent-bg)}

/* ---------- pricing cards ---------- */
{
  const grid = $('#pr-grid');
  const plans = [
    { n:'Starter', m:0, y:0, d:'For trying it out on a side project.', b:'Start free', f:['3 projects','Community support','Core components'] },
    { n:'Pro', m:24, y:19, d:'For freelancers and small teams shipping every week.', b:'Get Pro', pop:true, f:['Unlimited projects','Figma files','Priority support'] },
    { n:'Team', m:48, y:38, d:'For product teams who need shared libraries.', b:'Talk to us', f:['Everything in Pro','Shared workspaces','SSO and audit log'] }
  ];
  grid.innerHTML = plans.map((p, i) => `<div class="pr-c ${p.pop ? 'pop' : ''}"><div class="pr-n">${p.n}${p.pop ? '<span class="tag">Popular</span>' : ''}</div><div class="pr-p"><b data-i="${i}">$${p.m}</b><span>${p.m ? '/ seat / month' : 'forever'}</span></div><div class="pr-d">${p.d}</div><button class="btn ${p.pop ? 'primary' : ''}">${p.b}</button><div class="pr-f">${p.f.map(f => `<span>${ic('check','sm')}${f}</span>`).join('')}</div></div>`).join('');
  const nums = $$('.pr-p b', grid);
  const shown = plans.map(p => p.m);
  segInit($('#pr-seg'), v => {
    plans.forEach((p, i) => {
      const from = shown[i], to = v === 'y' ? p.y : p.m, t0 = performance.now(), el = nums[i];
      const step = now => { const t = reduce ? 1 : Math.min(1, (now - t0) / 500), e = 1 - Math.pow(1 - t, 3); el.textContent = '$' + Math.round(from + (to - from) * e); if (t < 1) requestAnimationFrame(step); };
      shown[i] = to; requestAnimationFrame(step);
    });
  });
  $$('.pr-c .btn', grid).forEach(b => b.addEventListener('click', () => { Sound.play('select'); showToast(b.textContent); }));
}
